import type { ButtonHTMLAttributes } from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";

const filledShadow = "shadow-[inset_0_1px_0_rgba(255,255,255,0.14)]";

/* Pill-shaped by default: the app's core button style. Explicit symmetric
 * padding (not a fixed height) so the top/bottom spacing is always equal. */
export const buttonVariants = cva(
  `inline-flex items-center justify-center font-medium select-none
   transition-[transform,background-color,opacity] duration-150 ease-out
   active:scale-[0.96] disabled:opacity-50 disabled:pointer-events-none`,
  {
    variants: {
      variant: {
        /* disabled: a quiet well, not a dimmed slab (in dark mode half an ink fill reads as a heavy grey block) */
        primary: `bg-ink text-canvas hover:opacity-90 dark:bg-ink dark:text-canvas ${filledShadow} disabled:bg-hover-2 disabled:text-ink-3 disabled:opacity-100 disabled:shadow-[inset_0_0_0_1px_var(--line)]`,
        secondary: "bg-surface text-ink shadow-btn hover:bg-inset aria-expanded:bg-hover",
        ghost: "bg-hover-2 text-ink hover:bg-line-strong",
        accent: `bg-accent-blue text-white hover:bg-accent-ink ${filledShadow}`,
        danger: `bg-red text-white hover:brightness-95 ${filledShadow}`,
        /* transparent until hovered: for dense toolbars/action rows */
        quiet: "text-ink hover:bg-hover",
      },
      size: {
        /* compact toolbar pill: fixed height, lighter weight */
        xs: "h-7 rounded-full px-2.5 text-[12px] font-normal leading-none gap-1",
        /* canonical action pill: 27px tall, roomy sides */
        sm: "h-[27px] px-3 text-[13px] leading-none rounded-full gap-1.5",
        md: "px-4 py-[9px] text-sm leading-none rounded-full gap-2",
      },
    },
    defaultVariants: { variant: "secondary", size: "md" },
  },
);

export type ButtonVariant = NonNullable<VariantProps<typeof buttonVariants>["variant"]>;

export function Button({ variant, size, className, ...props }: ButtonHTMLAttributes<HTMLButtonElement> & VariantProps<typeof buttonVariants>) {
  return <button type="button" className={cn(buttonVariants({ variant, size }), className)} {...props} />;
}

import type { ReactNode } from "react";

/** Monospace token chip, for code values like `agent.runtime`. Beautiful UI's Chip. */
export function Chip({ children, tone = "neutral", className = "" }: { children: ReactNode; tone?: "neutral" | "accent" | "orange"; className?: string }) {
  const tones = {
    neutral: "bg-inset text-ink-2",
    accent: "bg-accent-tint text-accent-ink",
    orange: "bg-orange-tint text-orange",
  };
  return <code className={`inline rounded-md px-1.5 py-0.5 align-[-1px] font-mono text-[12px] leading-none ${tones[tone]} ${className}`}>{children}</code>;
}

type Tone = "neutral" | "green" | "orange" | "red" | "accent";

const TONES: Record<Tone, { cls: string; ring: string }> = {
  neutral: { cls: "bg-field text-ink-2", ring: "var(--shadow-hairline)" },
  green: { cls: "bg-green-tint text-green", ring: "0 0 0 1px color-mix(in oklch, var(--green) 28%, transparent)" },
  orange: { cls: "bg-orange-tint text-orange", ring: "0 0 0 1px color-mix(in oklch, var(--orange) 28%, transparent)" },
  red: { cls: "bg-red-tint text-red", ring: "0 0 0 1px color-mix(in oklch, var(--red) 28%, transparent)" },
  accent: { cls: "bg-accent-tint text-accent-ink", ring: "0 0 0 1px color-mix(in oklch, var(--accent-blue) 28%, transparent)" },
};

/**
 * Inline value badge: a plain value (a date, a name, a count) set off in prose. Softer than a
 * StatusPill (no dot) and not a mono token (see Chip). Beautiful UI's ValuePill.
 */
export function ValuePill({ children, tone = "neutral", className = "" }: { children: ReactNode; tone?: Tone; className?: string }) {
  const t = TONES[tone];
  return (
    <span className={`mx-0.5 inline-flex items-center rounded-full px-1.5 py-0 align-middle text-[12px] font-medium ${t.cls} ${className}`} style={{ boxShadow: t.ring }}>
      {children}
    </span>
  );
}

import { type ReactNode, useEffect, useState } from "react";

/* ---------------------------------------------------------
 * CODE BLOCK
 * Beautiful UI's editor panel, fed by the app: a file's
 * name, a copy button, and its lines numbered and coloured
 * (strings and numbers orange, keywords blue, keys and
 * calls in ink). Lines wrap.
 * --------------------------------------------------------- */

const KEYWORDS = new Set(["import", "from", "export", "default", "async", "function", "const", "let", "var", "await", "return", "if", "else", "for", "while", "new", "throw", "try", "catch", "null", "true", "false", "undefined"]);
const TOKEN =
  /("(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|`[^`]*`|-?\b\d+(?:\.\d+)?(?:e[+-]?\d+)?\b|\b(?:import|from|export|default|async|function|const|let|var|await|return|if|else|for|while|new|throw|try|catch|null|true|false|undefined)\b|[A-Za-z_$][\w$]*(?=\s*\())/g;

function highlight(text: string): ReactNode[] {
  const nodes: ReactNode[] = [];
  let last = 0;
  let k = 0;
  for (const m of text.matchAll(TOKEN)) {
    const idx = m.index ?? 0;
    const t = m[0];
    if (idx > last) nodes.push(<span key={k++}>{text.slice(last, idx)}</span>);
    const end = idx + t.length;
    let color: string;
    let weight: number | undefined;
    // a JSON key: a string a colon follows
    if (t.startsWith('"') && /^\s*:/.test(text.slice(end))) {
      color = "var(--ink)";
      weight = 500;
    } else if (/^["'`]/.test(t) || /^-?\d/.test(t)) color = "var(--orange)";
    else if (KEYWORDS.has(t)) color = "var(--accent-ink)";
    else {
      color = "var(--ink)";
      weight = 500;
    }
    nodes.push(
      <span key={k++} style={{ color, fontWeight: weight }}>
        {t}
      </span>,
    );
    last = end;
  }
  if (last < text.length) nodes.push(<span key={k++}>{text.slice(last)}</span>);
  return nodes;
}

function FileIcon() {
  return (
    <svg aria-hidden width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" className="shrink-0 text-ink-3">
      <path d="M17.25 6.75 22.5 12l-5.25 5.25m-10.5 0L1.5 12l5.25-5.25m7.5-3-4.5 16.5" />
    </svg>
  );
}

export default function CodeBlock({ code, filename, meta, className = "" }: { code: string; filename: string; /** after the name: what the code is */ meta?: ReactNode; className?: string }) {
  const [copied, setCopied] = useState(false);
  const lines = code.split("\n");
  // the gutter grows with the line numbers' digits
  const gutter = Math.max(20, String(lines.length).length * 7 + 8);

  useEffect(() => {
    if (!copied) return;
    const timer = setTimeout(() => setCopied(false), 1500);
    return () => clearTimeout(timer);
  }, [copied]);

  const copy = () => {
    navigator.clipboard?.writeText(code).then(
      () => setCopied(true),
      () => undefined,
    );
  };

  return (
    <div className={`w-full overflow-hidden rounded-card bg-surface shadow-card ${className}`}>
      <div className="flex h-11 items-center gap-2 border-b border-line px-4 text-[12.5px]">
        <span className="inline-flex min-w-0 items-center gap-[7px]">
          <FileIcon />
          <span className="truncate font-mono leading-none text-ink">{filename}</span>
        </span>
        {meta !== undefined && <span className="truncate text-[12px] text-ink-3">{meta}</span>}
        <button
          type="button"
          aria-label="Copy code"
          onClick={copy}
          className={`-mr-1 ml-auto flex h-6 shrink-0 items-center gap-1 rounded-[6px] px-1.5 text-[12px] font-medium transition-colors duration-100 hover:bg-hover ${copied ? "text-green" : "text-ink-3 hover:text-ink"}`}
        >
          {copied ? (
            <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
              <path d="M20 6L9 17l-5-5" />
            </svg>
          ) : (
            <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
              <rect x="9" y="9" width="12" height="12" rx="2.5" />
              <path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1" />
            </svg>
          )}
          {copied ? "Copied" : "Copy"}
        </button>
      </div>

      <div className="py-3 font-mono text-[12.5px] leading-[1.65] text-ink-2">
        <div className="relative">
          <span className="pointer-events-none absolute inset-y-0 w-px bg-line" style={{ left: gutter }} />
          {lines.map((line, i) => (
            <div key={i} className="grid items-start" style={{ gridTemplateColumns: `${gutter}px minmax(0,1fr)` }}>
              <span className="select-none text-center text-[11px] text-ink-3">{i + 1}</span>
              <code className="pr-3 pl-2 break-words whitespace-pre-wrap">{highlight(line)}</code>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

import type { ReactNode } from "react";

/* ---------------------------------------------------------
 * CONTEXT CARDS
 * Beautiful UI's retrieved chunks, fed by real data: a header
 * with a count, then one card each (a title, a figure, what it
 * says, and its source as a chip that opens it). They enter
 * once, then remain.
 * --------------------------------------------------------- */

export type ContextChunk = {
  key: string;
  title: string;
  /** a short figure at the bar's end: "1,250 characters" */
  meta?: string;
  body: string;
  /** the chip: where it came from */
  source: string;
  /** opens in a new tab */
  href?: string;
  /** a few letters on the chip's mark: "WEB" */
  badge: string;
  /** the mark's colour class: "bg-accent-blue" */
  tone: string;
};

/** The header the harness gives a group of context: its name and a count. */
export function ContextHeader({ title, count }: { title: string; count: ReactNode }) {
  return (
    <div className="flex items-center gap-2 px-0.5" style={{ animation: "fade-in 400ms ease-out both" }}>
      <span className="text-[13px] font-semibold text-ink">{title}</span>
      <span className="inline-flex h-5 items-center rounded-md bg-inset px-1.5 text-[11.5px] font-medium text-ink-2 shadow-hairline tabular-nums">{count}</span>
    </div>
  );
}

function SourceChip({ chunk }: { chunk: ContextChunk }) {
  const inner = (
    <>
      <span className={`flex h-3.5 min-w-3.5 shrink-0 items-center justify-center rounded-[4px] px-0.5 ${chunk.tone} text-[7px] font-bold text-white`}>{chunk.badge}</span>
      <span className="min-w-0 truncate">{chunk.source}</span>
      {chunk.href !== undefined && (
        <svg width="9" height="9" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden className="shrink-0">
          <path d="M7 17L17 7M7 7h10v10" />
        </svg>
      )}
    </>
  );
  const className = "inline-flex h-6 max-w-full items-center gap-1.5 rounded-full bg-inset px-2 text-[12px] font-medium text-ink-2 shadow-btn transition-[background-color] duration-300 hover:bg-hover";
  return chunk.href === undefined ? (
    <span className={className}>{inner}</span>
  ) : (
    <a className={className} href={chunk.href} target="_blank" rel="noreferrer noopener" title={chunk.href}>
      {inner}
    </a>
  );
}

export default function ContextCards({ chunks, header, className = "" }: { chunks: ContextChunk[]; header: string; className?: string }) {
  return (
    <div className={`flex w-full flex-col gap-2 ${className}`}>
      <ContextHeader title={header} count={chunks.length} />
      {chunks.map((chunk, i) => (
        <div key={chunk.key} className="overflow-hidden rounded-card bg-surface shadow-card" style={{ animation: `fade-up 400ms cubic-bezier(0.23,1,0.32,1) ${Math.min(i, 8) * 60}ms both` }}>
          <div className="flex items-center gap-2.5 border-b border-line px-3 py-2.5">
            <span className="flex min-w-0 items-center gap-1.5 text-[13px] font-medium text-ink">
              <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" aria-hidden className="shrink-0">
                <path d="M4 6h16M4 12h16M4 18h10" />
              </svg>
              <span className="truncate" title={chunk.title}>
                {chunk.title}
              </span>
            </span>
            {chunk.meta !== undefined && <span className="ml-auto shrink-0 text-[12px] text-ink-3 tabular-nums">{chunk.meta}</span>}
          </div>
          {chunk.body !== "" && <p className="line-clamp-4 px-3 pt-2 pb-1 text-[12.5px] leading-relaxed text-ink-2 [overflow-wrap:anywhere]">{chunk.body}</p>}
          <div className="px-3 pt-1 pb-3">
            <SourceChip chunk={chunk} />
          </div>
        </div>
      ))}
    </div>
  );
}

import type { ReactNode } from "react";

/* ---------------------------------------------------------
 * EMPTY STATE
 * Beautiful UI's SearchList "no results", fed by the app: a
 * glyph in a quiet square, what is (not) there, and a hint.
 * --------------------------------------------------------- */

export default function EmptyState({ icon, title, hint }: { icon?: ReactNode; title: string; hint?: ReactNode }) {
  return (
    <div className="flex flex-col items-center justify-center gap-1 px-4 py-8 text-center" style={{ animation: "fade-in 250ms ease-out both" }}>
      <span className="mb-1.5 flex size-8 items-center justify-center rounded-control bg-inset text-ink-3 shadow-hairline [&_svg]:size-[15px]">
        {icon ?? (
          <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" aria-hidden>
            <circle cx="11" cy="11" r="7" />
            <path d="M21 21l-4.3-4.3" />
          </svg>
        )}
      </span>
      <span className="text-[13px] font-medium text-ink">{title}</span>
      {hint !== undefined && <span className="max-w-sm text-[12px] text-ink-3">{hint}</span>}
    </div>
  );
}

import type { ReactNode } from "react";

/* ---------------------------------------------------------
 * FILTER TABLE
 * Beautiful UI's filter chips and status pills, fed by the
 * app: chips with a dot and a count that pick what a table
 * shows, and the electric pills a state shows as in a cell.
 * --------------------------------------------------------- */

export type PillTone = "green" | "orange" | "blue" | "red" | "neutral";

/** The dot of each tone, as the chips show it. */
export const TONE_DOT: Record<PillTone, string> = {
  green: "var(--green)",
  orange: "var(--orange)",
  blue: "var(--accent-blue)",
  red: "var(--red)",
  neutral: "var(--ink-3)",
};

export type Filter<K extends string> = { key: K; label: string; count?: number; tone?: PillTone };

/** Chips that pick one of `filters`; each with its dot (a tone) and its count. */
export function FilterChips<K extends string>({ filters, value, onChange, label }: { filters: Filter<K>[]; value: K; onChange: (key: K) => void; label: string }) {
  return (
    <div role="group" aria-label={label} className="-mx-1 flex items-center gap-1 overflow-x-auto px-1 py-1" style={{ scrollbarWidth: "none" }}>
      {filters.map((filter) => {
        const active = value === filter.key;
        return (
          <button
            key={filter.key}
            type="button"
            aria-pressed={active}
            onClick={() => onChange(filter.key)}
            className={`flex h-6.5 shrink-0 items-center gap-1.5 rounded-full px-2.5 text-[12px] font-medium transition-[background-color,box-shadow,color] duration-200 ${active ? "bg-surface text-ink shadow-btn" : "text-ink-2 hover:bg-hover"}`}
          >
            {filter.tone !== undefined && <span className="size-1.5 rounded-full" style={{ background: TONE_DOT[filter.tone] }} />}
            {filter.label}
            {filter.count !== undefined && <span className={`rounded-[4px] px-1 text-[10.5px] tabular-nums ${active ? "bg-field text-ink-2" : "text-ink-3"}`}>{filter.count}</span>}
          </button>
        );
      })}
    </div>
  );
}

/** A state in a table's cell: the filter table's pill, its colours mixed from the tone's hue. */
export function StatePill({ tone, children, title }: { tone: PillTone; children: ReactNode; title?: string }) {
  return (
    <span title={title} className={`filter-status filter-status-${tone} inline-flex h-[23px] shrink-0 items-center whitespace-nowrap rounded-[8px] px-[7px] text-[13px] font-medium`}>
      {children}
    </span>
  );
}

import { useRef, useState, type ReactNode } from "react";

type GlideMenuProps = {
  children: ReactNode;
  className?: string;
  highlightClassName?: string;
  rowSelector?: string;
};

/** A single hover layer that glides between interactive menu rows. */
export default function GlideMenu({
  children,
  className = "",
  highlightClassName = "inset-x-0 rounded-[8px] bg-hover",
  rowSelector = "[data-menu-row]",
}: GlideMenuProps) {
  const ref = useRef<HTMLDivElement>(null);
  const [box, setBox] = useState<{ top: number; height: number } | null>(null);
  const [visible, setVisible] = useState(false);

  const moveTo = (target: EventTarget | null) => {
    const container = ref.current;
    if (!(target instanceof Element) || !container) return;
    const row = target.closest(rowSelector);
    if (!(row instanceof HTMLElement) || !container.contains(row)) return;
    const containerRect = container.getBoundingClientRect();
    const rowRect = row.getBoundingClientRect();
    setBox({ top: rowRect.top - containerRect.top, height: rowRect.height });
    setVisible(true);
  };

  return (
    <div
      ref={ref}
      onMouseOver={(event) => moveTo(event.target)}
      onMouseLeave={() => setVisible(false)}
      onFocusCapture={(event) => moveTo(event.target)}
      onBlurCapture={(event) => {
        if (!ref.current?.contains(event.relatedTarget as Node | null)) setVisible(false);
      }}
      className={`group/glide-menu relative ${className}`}
    >
      <span
        aria-hidden
        className={`pointer-events-none absolute ${highlightClassName}`}
        style={{
          top: box?.top ?? 0,
          height: box?.height ?? 0,
          opacity: box && visible ? 1 : 0,
          transition:
            "top 220ms cubic-bezier(0.23,1,0.32,1), height 220ms cubic-bezier(0.23,1,0.32,1), opacity 150ms ease",
        }}
      />
      {children}
    </div>
  );
}

import { useEffect, useState } from "react";

/* ---------------------------------------------------------
 * LOADING STATE: pixel-grid loader for long-running work
 *
 *   Drive: square cells, a chevron wavefront driving right
 *   Dots:  the same wavefront, circular cells
 *   Orbit: a comet lapping the grid perimeter
 *
 * Paired with a shimmering label and the time elapsed since
 * `since` (epoch ms; by default since it appeared), in mono
 * tabular figures.
 * --------------------------------------------------------- */

const chevron = Array.from({ length: 9 }, (_, i) => {
  const r = Math.floor(i / 3),
    c = i % 3;
  return (c + Math.abs(r - 1)) * 90;
});

const ORBIT_ORDER = [0, 1, 2, 5, 8, 7, 6, 3];
const orbit = Array.from({ length: 9 }, (_, i) => {
  const k = ORBIT_ORDER.indexOf(i);
  return k === -1 ? null : k * 110;
});

const PATTERNS: Record<string, { delays: (number | null)[]; dur: number; round: boolean }> = {
  Drive: { delays: chevron, dur: 650, round: false },
  Dots: { delays: chevron, dur: 650, round: true },
  Orbit: { delays: orbit, dur: 950, round: false },
};

export function LoaderGrid({ variant = "Dots" }: { variant?: string }) {
  const { delays, dur, round } = PATTERNS[variant] ?? (PATTERNS.Dots as (typeof PATTERNS)[string]);
  return (
    <span aria-hidden className="grid shrink-0 grid-cols-[repeat(3,4px)] gap-[1.5px]">
      {delays.map((delay, index) => (
        <span
          key={index}
          className={`size-[4px] bg-ink ${round ? "rounded-full" : "rounded-[1px]"}`}
          style={{
            opacity: delay === null ? 0.07 : 0.15,
            animation: delay === null ? "none" : `pixel-on ${dur}ms ease-in-out ${delay}ms infinite`,
          }}
        />
      ))}
    </span>
  );
}

function useElapsed(since: number | undefined) {
  const [start] = useState(() => since ?? Date.now());
  const [now, setNow] = useState(() => Date.now());
  useEffect(() => {
    const t = setInterval(() => setNow(Date.now()), 100);
    return () => clearInterval(t);
  }, []);
  const total = Math.max(0, now - start) / 1000;
  if (total < 60) return `${total.toFixed(1)}s`;
  return `${Math.floor(total / 60)}m ${(total % 60).toFixed(1)}s`;
}

export default function LoadingState({ label = "Working", variant = "Dots", since }: { label?: string; variant?: string; since?: number }) {
  const elapsed = useElapsed(since);
  return (
    <div role="status" className="flex w-fit items-center gap-2.5">
      <LoaderGrid variant={variant} />
      <span
        className="bg-clip-text text-[13px] font-medium text-transparent"
        style={{
          backgroundImage: "linear-gradient(90deg, var(--ink-3) 35%, var(--ink) 50%, var(--ink-3) 65%)",
          backgroundSize: "200% 100%",
          animation: "shimmer-text 1.4s linear infinite",
        }}
      >
        {label}
      </span>
      <span className="font-mono text-[12px] text-ink-3 tabular-nums">{elapsed}</span>
    </div>
  );
}

import type { ReactNode } from "react";
import { LoaderGrid } from "./LoadingState";

/* ---------------------------------------------------------
 * PAGE
 * An operator's page in the harness's voice: the view's name
 * quiet above what it says now (the home's two-tone heading),
 * a line of context, then its sections, each a small title
 * with its filters and a table or a panel. It fills the pane
 * and scrolls itself (a view's page with `fill: true`).
 * --------------------------------------------------------- */

export function Page({ eyebrow, title, aside, description, children }: { eyebrow: string; title?: ReactNode; aside?: ReactNode; description?: ReactNode; children?: ReactNode }) {
  return (
    <div className="min-h-0 flex-1 overflow-y-auto">
      <div className="mx-auto w-full max-w-[1200px] px-4 pt-10 pb-16 sm:px-8 lg:px-12" style={{ animation: "fade-up 450ms cubic-bezier(0.23,1,0.32,1) both" }}>
        <header className="flex flex-wrap items-end justify-between gap-x-6 gap-y-3">
          <h1 className="min-w-0 text-[26px] leading-tight font-normal tracking-[-0.02em] text-ink">
            <span className="block text-ink-3">{eyebrow}</span>
            {title !== undefined && <span className="block">{title}</span>}
          </h1>
          {aside !== undefined && <div className="flex shrink-0 items-center gap-2">{aside}</div>}
        </header>
        {description !== undefined && <div className="mt-3 max-w-[720px] text-[13.5px] leading-relaxed text-ink-2">{description}</div>}
        <div className="mt-8 flex flex-col gap-10">{children}</div>
      </div>
    </div>
  );
}

/** One part of a page: its title (and a figure), what filters it on the right, then its body. */
export function Section({ title, meta, tools, children }: { title: string; meta?: ReactNode; tools?: ReactNode; children: ReactNode }) {
  return (
    <section className="flex min-w-0 flex-col gap-2.5">
      <div className="flex flex-wrap items-center justify-between gap-x-4 gap-y-2">
        <h2 className="flex items-baseline gap-2 text-[13px] font-semibold text-ink">
          {title}
          {meta !== undefined && <span className="text-[12.5px] font-normal text-ink-3">{meta}</span>}
        </h2>
        {tools !== undefined && <div className="flex min-w-0 flex-wrap items-center gap-2">{tools}</div>}
      </div>
      {children}
    </section>
  );
}

/** A page still reading its data. */
export function PageLoading({ eyebrow }: { eyebrow: string }) {
  return (
    <Page eyebrow={eyebrow}>
      <div className="flex items-center gap-2.5 text-[13px] text-ink-3">
        <LoaderGrid /> Loading
      </div>
    </Page>
  );
}

import { useEffect, useLayoutEffect, useRef, useState, type ReactNode } from "react";

/* ---------------------------------------------------------
 * PROMPT BAR
 * Beautiful UI's hero composer, with real controls: the "+"
 * menu (add images, web search for the next message), the
 * "/" menu (the commands the App registered, filtered as you
 * type; none: a quiet "No commands", and the text is sent as
 * a message), and a picker where the harness picks its
 * model, a dropdown even with one option. While a run goes
 * the send button stops it. Enter sends (or runs "/name
 * args" when it names a command), Shift+Enter breaks a line;
 * in a menu, arrows move, Enter picks (a command whose whole
 * name is typed runs), Tab completes, Escape closes.
 * --------------------------------------------------------- */

function Icon({ children, size = 15, strokeWidth = 1.8 }: { children: ReactNode; size?: number; strokeWidth?: number }) {
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={strokeWidth} strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
      {children}
    </svg>
  );
}

const GLYPHS = {
  image: (
    <g>
      <rect x="3" y="3" width="18" height="18" rx="2.5" />
      <circle cx="8.5" cy="8.5" r="1.5" />
      <path d="m21 15-5-5L5 21" />
    </g>
  ),
  globe: (
    <g>
      <circle cx="12" cy="12" r="10" />
      <path d="M2 12h20M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z" />
    </g>
  ),
  check: <path d="M20 6L9 17l-5-5" />,
  close: <path d="M18 6L6 18M6 6l12 12" />,
};

export type PickerOption = { key: string; name: string; tag?: string };

export type Picker = {
  /** what it chooses, for its label: "assistant" */
  label: string;
  options: PickerOption[];
  value: string | undefined;
  /** absent: the value is shown, not chosen */
  onChange?: (key: string) => void;
  /** a line under the options: what choosing does */
  note?: string;
};

/** The images the composer takes: their types, how many, how large each (and in all), in bytes. */
export type ImageLimits = { types: readonly string[]; count: number; bytes: number; totalBytes?: number };

/** An image to send: its bytes in base64, without a `data:` prefix. */
export type ComposerImage = { name: string; mimeType: string; data: string };

/** What is sent: the text, the images, and whether the next message asks for a web search. */
export type ComposerMessage = { text: string; images: ComposerImage[]; webSearch: boolean };

/** A "/" command, as the App registered it (`GET /admin/api/commands`). */
export type Command = {
  /** without its slash: "new" */
  name: string;
  description: string;
  /** what it takes after its name: "<title>"; absent, it runs as soon as it is picked */
  argumentHint?: string;
};

/** "/name args": a command's name and what follows it, when the draft is one. */
const COMMAND_LINE = /^\/([a-z0-9][a-z0-9:-]*)(?:\s+([\s\S]*))?$/;

type Attached = { id: number; file: File; url: string };

type MenuRow = { key: string; name: string; hint?: string; desc: string; icon?: ReactNode; trailing?: ReactNode; disabled?: boolean; pick: () => void };

const megabytes = (bytes: number) => `${Math.round((bytes / 1024 / 1024) * 10) / 10} MB`;

/** A file's bytes in base64. */
function base64Of(file: File): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(String(reader.result).slice(String(reader.result).indexOf(",") + 1));
    reader.onerror = () => reject(reader.error ?? new Error(`${file.name} could not be read`));
    reader.readAsDataURL(file);
  });
}

let nextId = 0;

export default function PromptBar({
  placeholder,
  picker,
  onSend,
  busy = false,
  onStop,
  disabled = false,
  autoFocus = false,
  images,
  webSearch,
  commands = [],
  onCommand,
  commandsNote = "Type to search commands",
}: {
  placeholder?: string;
  picker?: Picker;
  /** sends the message; the draft is cleared once it resolves, kept when it throws */
  onSend: (message: ComposerMessage) => Promise<void> | void;
  /** a run is going: with an empty draft, the send button stops it */
  busy?: boolean;
  onStop?: () => void;
  disabled?: boolean;
  autoFocus?: boolean;
  /** "Add image" in the "+" menu; absent, the composer takes text only */
  images?: ImageLimits;
  /** "Web search" in the "+" menu: `available` when the assistant has the tool, else `unavailable` says why */
  webSearch?: { available: boolean; unavailable?: string };
  /** the "/" menu: the App's commands, by name */
  commands?: Command[];
  /** runs "/name args"; the draft is cleared once it resolves, kept when it throws */
  onCommand?: (name: string, args: string) => Promise<void> | void;
  /** the line under the commands */
  commandsNote?: string;
}) {
  const [draft, setDraft] = useState("");
  const [sending, setSending] = useState(false);
  const [attached, setAttached] = useState<Attached[]>([]);
  const [searching, setSearching] = useState(false);
  const [problem, setProblem] = useState<string>();
  const [dismissed, setDismissed] = useState(false);
  const [plusOpen, setPlusOpen] = useState(false);
  const [active, setActive] = useState(0);
  const [engaged, setEngaged] = useState(false);
  const [rowBox, setRowBox] = useState<{ top: number; height: number } | null>(null);
  const [modelOpen, setModelOpen] = useState(false);
  const [modelBox, setModelBox] = useState<{ top: number; height: number } | null>(null);
  const [modelHovered, setModelHovered] = useState<number | null>(null);
  const [modelMenuLeft, setModelMenuLeft] = useState(0);
  const [modelMenuBottom, setModelMenuBottom] = useState(0);
  const composerAnchorRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLTextAreaElement>(null);
  const fileRef = useRef<HTMLInputElement>(null);
  const modelRef = useRef<HTMLButtonElement>(null);
  const rowRefs = useRef<(HTMLButtonElement | null)[]>([]);
  const modelRowRefs = useRef<(HTMLButtonElement | null)[]>([]);
  const attachedRef = useRef(attached);
  attachedRef.current = attached;

  const options = picker?.options ?? [];
  const choosable = picker?.onChange !== undefined && options.length > 0;
  const chosen = options.find((option) => option.key === picker?.value);
  const canSearch = webSearch?.available === true;
  const webSearchOn = searching && canSearch;

  /* a "/" typed at the start opens the commands, filtered by what follows it */
  const slash = dismissed || plusOpen ? null : /^\/([\w:-]*)$/.exec(draft);
  const query = slash?.[1]?.toLowerCase() ?? "";
  const menu: "plus" | "slash" | null = plusOpen ? "plus" : slash !== null ? "slash" : null;

  const openPicker = () => {
    setPlusOpen(false);
    fileRef.current?.click();
  };
  const toggleSearch = () => {
    setPlusOpen(false);
    if (canSearch) setSearching((on) => !on);
    inputRef.current?.focus();
  };
  /* a command's draft: what the operator wrote names one of the App's commands */
  const commandOf = (text: string): { name: string; args: string } | undefined => {
    const line = COMMAND_LINE.exec(text.trim());
    const name = line?.[1];
    return name !== undefined && onCommand !== undefined && commands.some((command) => command.name === name) ? { name, args: (line?.[2] ?? "").trim() } : undefined;
  };

  const runCommand = async (name: string, args: string) => {
    if (onCommand === undefined) return;
    setSending(true);
    setPlusOpen(false);
    setModelOpen(false);
    try {
      await onCommand(name, args);
      setDraft("");
      setDismissed(false);
    } catch {
      // The caller says why; the draft stays.
    } finally {
      setSending(false);
      inputRef.current?.focus();
    }
  };

  /* picked from the menu: one that takes arguments waits for them, another runs at once */
  const pick = (command: Command) => {
    if (command.argumentHint !== undefined) {
      setDraft(`/${command.name} `);
      setDismissed(true);
      inputRef.current?.focus();
    } else void runCommand(command.name, "");
  };

  const rows: MenuRow[] =
    menu === "plus"
      ? [
          ...(images === undefined
            ? []
            : [
                {
                  key: "image",
                  name: "Add image",
                  desc: `${images.types.map((type) => type.replace("image/", "").toUpperCase()).join(", ")}, up to ${megabytes(images.bytes)}`,
                  icon: <Icon size={15}>{GLYPHS.image}</Icon>,
                  pick: openPicker,
                },
              ]),
          ...(webSearch === undefined
            ? []
            : [
                {
                  key: "search",
                  name: "Web search",
                  desc: canSearch ? (webSearchOn ? "On for the next message" : "Search the web for the next message") : (webSearch.unavailable ?? "Not available"),
                  icon: <Icon size={15}>{GLYPHS.globe}</Icon>,
                  trailing: webSearchOn ? (
                    <span className="shrink-0 text-ink">
                      <Icon size={13} strokeWidth={2.5}>
                        {GLYPHS.check}
                      </Icon>
                    </span>
                  ) : undefined,
                  disabled: !canSearch,
                  pick: toggleSearch,
                },
              ]),
        ]
      : menu === "slash"
        ? commands
            .filter((command) => command.name.startsWith(query))
            .map((command) => ({ key: command.name, name: `/${command.name}`, ...(command.argumentHint !== undefined && { hint: command.argumentHint }), desc: command.description, pick: () => pick(command) }))
        : [];

  useEffect(() => {
    setActive(0);
    setEngaged(false);
  }, [menu, query]);

  /* a single highlight glides to the active row instead of each row toggling its own background */
  useLayoutEffect(() => {
    const target = rowRefs.current[active];
    if (target) setRowBox({ top: target.offsetTop, height: target.offsetHeight });
  }, [menu, query, active, rows.length]);

  /* the same in the picker's menu: the hovered row, else the chosen one */
  const modelIndex = options.findIndex((option) => option.key === picker?.value);
  useLayoutEffect(() => {
    if (!modelOpen) return;
    const target = modelRowRefs.current[modelHovered ?? modelIndex];
    if (target) setModelBox({ top: target.offsetTop, height: target.offsetHeight });
  }, [modelOpen, modelHovered, modelIndex]);

  /* the picker's menu sits outside the clipped composer: align it to the trigger by measurement */
  useLayoutEffect(() => {
    if (!modelOpen || !composerAnchorRef.current || !modelRef.current) return;
    const anchorRect = composerAnchorRef.current.getBoundingClientRect();
    const triggerRect = modelRef.current.getBoundingClientRect();
    setModelMenuLeft(Math.max(0, Math.min(triggerRect.left - anchorRect.left, anchorRect.width - 224)));
    setModelMenuBottom(anchorRect.bottom - triggerRect.top + 8);
  }, [modelOpen]);

  useEffect(() => {
    if (!modelOpen) setModelHovered(null);
  }, [modelOpen]);

  /* grow with the text, to a compact maximum */
  useLayoutEffect(() => {
    const input = inputRef.current;
    if (!input) return;
    const maxHeight = 200;
    input.style.height = "0px";
    const contentHeight = input.scrollHeight;
    input.style.height = `${Math.min(contentHeight, maxHeight)}px`;
    input.style.overflowY = contentHeight > maxHeight ? "auto" : "hidden";
  }, [draft]);

  /* clicking anywhere outside the composer, or Escape wherever the focus is, closes the menus */
  useEffect(() => {
    if (!modelOpen && !plusOpen) return;
    const closeAll = () => {
      setModelOpen(false);
      setPlusOpen(false);
    };
    const close = (event: PointerEvent) => {
      if (!(event.target as Element).closest("[data-promptbar]")) closeAll();
    };
    const escape = (event: KeyboardEvent) => event.key === "Escape" && closeAll();
    document.addEventListener("pointerdown", close);
    document.addEventListener("keydown", escape);
    return () => {
      document.removeEventListener("pointerdown", close);
      document.removeEventListener("keydown", escape);
    };
  }, [modelOpen, plusOpen]);

  /* what the composer refused goes away after a while */
  useEffect(() => {
    if (problem === undefined) return;
    const timer = setTimeout(() => setProblem(undefined), 6000);
    return () => clearTimeout(timer);
  }, [problem]);

  /* the thumbnails' object URLs are released with the composer */
  useEffect(() => () => attachedRef.current.forEach((each) => URL.revokeObjectURL(each.url)), []);

  const attach = (files: File[]) => {
    if (images === undefined || files.length === 0) return;
    const taken: Attached[] = [];
    let total = attached.reduce((sum, each) => sum + each.file.size, 0);
    let refused: string | undefined;
    for (const file of files) {
      if (attached.length + taken.length >= images.count) refused ??= `At most ${images.count} images a message`;
      else if (!images.types.includes(file.type)) refused ??= `${file.name}: not a ${images.types.map((type) => type.replace("image/", "").toUpperCase()).join(", ")} image`;
      else if (file.size > images.bytes) refused ??= `${file.name}: larger than ${megabytes(images.bytes)}`;
      else if (images.totalBytes !== undefined && total + file.size > images.totalBytes) refused ??= `The images of a message are at most ${megabytes(images.totalBytes)} in all here`;
      else {
        total += file.size;
        taken.push({ id: nextId++, file, url: URL.createObjectURL(file) });
      }
    }
    setProblem(refused);
    if (taken.length > 0) setAttached((current) => [...current, ...taken]);
    inputRef.current?.focus();
  };

  const detach = (id: number) => {
    setAttached((current) => {
      const gone = current.find((each) => each.id === id);
      if (gone !== undefined) URL.revokeObjectURL(gone.url);
      return current.filter((each) => each.id !== id);
    });
    inputRef.current?.focus();
  };

  const canSend = (draft.trim().length > 0 || attached.length > 0) && !sending && !disabled;
  const stopping = busy && onStop !== undefined && draft.trim().length === 0 && attached.length === 0;

  const send = async () => {
    if (!canSend) return;
    const command = attached.length === 0 ? commandOf(draft) : undefined;
    if (command !== undefined) return runCommand(command.name, command.args);
    setSending(true);
    setModelOpen(false);
    setPlusOpen(false);
    try {
      const read = await Promise.all(attached.map(async ({ file }) => ({ name: file.name, mimeType: file.type, data: await base64Of(file) })));
      await onSend({ text: draft.trim(), images: read, webSearch: webSearchOn });
      setDraft("");
      attached.forEach((each) => URL.revokeObjectURL(each.url));
      setAttached([]);
      setSearching(false);
      setProblem(undefined);
    } catch {
      // The caller says why; the draft stays.
    } finally {
      setSending(false);
      inputRef.current?.focus();
    }
  };

  return (
    <div data-promptbar className="w-full">
      <input
        ref={fileRef}
        type="file"
        hidden
        multiple
        accept={images?.types.join(",")}
        onChange={(event) => {
          attach([...(event.target.files ?? [])]);
          event.target.value = "";
        }}
      />
      <div ref={composerAnchorRef} className="relative">
        {/* -- "+" and "/" menu -- */}
        {menu !== null && (
          <div
            role="listbox"
            aria-label={menu === "plus" ? "Add to the message" : "Commands"}
            onMouseLeave={() => setEngaged(false)}
            className="absolute inset-x-0 bottom-full z-10 mb-2 rounded-[10px] bg-surface p-1 shadow-raised"
            style={{ animation: "pop-in 180ms cubic-bezier(0.23,1,0.32,1) both", transformOrigin: "bottom center" }}
          >
            {/* single gliding highlight: appears once a row is hovered or reached with the keys */}
            <span
              aria-hidden
              className="pointer-events-none absolute inset-x-1 rounded-[6px] bg-hover"
              style={{
                top: rowBox?.top ?? 0,
                height: rowBox?.height ?? 0,
                opacity: rowBox && engaged && rows.length > 0 ? 1 : 0,
                transition: "top 220ms cubic-bezier(0.23,1,0.32,1), height 220ms cubic-bezier(0.23,1,0.32,1), opacity 150ms ease",
              }}
            />
            {rows.map((row, i) => (
              <button
                key={row.key}
                type="button"
                role="option"
                aria-selected={engaged && i === active}
                disabled={row.disabled}
                ref={(el) => {
                  rowRefs.current[i] = el;
                }}
                onMouseDown={(event) => event.preventDefault()}
                onMouseEnter={() => {
                  setActive(i);
                  setEngaged(true);
                }}
                onClick={() => row.pick()}
                className="relative z-10 flex h-9 w-full items-center gap-2.5 rounded-[6px] px-2 text-left disabled:cursor-default"
              >
                {row.icon !== undefined && <span className={`flex size-5.5 shrink-0 items-center justify-center ${row.disabled ? "text-ink-3" : "text-ink-2"}`}>{row.icon}</span>}
                <span className={`shrink-0 text-[12.5px] font-medium ${row.disabled ? "text-ink-3" : "text-ink"}`}>{row.name}</span>
                {row.hint !== undefined && <span className="shrink-0 font-mono text-[11.5px] text-ink-3">{row.hint}</span>}
                <span className="min-w-0 flex-1 truncate text-[12px] text-ink-3">{row.desc}</span>
                {row.trailing}
              </button>
            ))}
            {rows.length === 0 && (
              <div className="flex h-9 items-center px-2 text-[12px] text-ink-3">{menu === "slash" && commands.length === 0 ? "No commands" : `No command “/${query}”`}</div>
            )}
            {menu === "slash" && rows.length > 0 && <div className="mt-1 border-t border-line px-2 pt-1.5 pb-1 text-[11px] text-ink-3">{commandsNote}</div>}
          </div>
        )}

        {/* -- picker menu -- */}
        {modelOpen && (
          <div
            role="listbox"
            aria-label={`Choose the ${picker?.label ?? "option"}`}
            onMouseLeave={() => setModelHovered(null)}
            className="absolute z-10 w-56 rounded-[10px] bg-surface p-1 shadow-raised"
            style={{ left: modelMenuLeft, bottom: modelMenuBottom, animation: "pop-in 180ms cubic-bezier(0.23,1,0.32,1) both", transformOrigin: "bottom left" }}
          >
            <span
              aria-hidden
              className="pointer-events-none absolute inset-x-1 rounded-[6px] bg-hover"
              style={{
                top: modelBox?.top ?? 0,
                height: modelBox?.height ?? 0,
                opacity: modelBox && modelHovered !== null ? 1 : 0,
                transition: "top 220ms cubic-bezier(0.23,1,0.32,1), height 220ms cubic-bezier(0.23,1,0.32,1), opacity 150ms ease",
              }}
            />
            {options.map((option, i) => (
              <button
                key={option.key}
                type="button"
                role="option"
                aria-selected={option.key === picker?.value}
                ref={(el) => {
                  modelRowRefs.current[i] = el;
                }}
                onMouseDown={(event) => event.preventDefault()}
                onMouseEnter={() => setModelHovered(i)}
                onClick={() => {
                  setModelOpen(false);
                  inputRef.current?.focus();
                  if (option.key !== picker?.value) picker?.onChange?.(option.key);
                }}
                className="relative z-10 flex h-7.5 w-full items-center gap-2 rounded-[6px] px-2 text-left"
              >
                <span className="min-w-0 flex-1 truncate text-[12.5px] font-medium text-ink">{option.name}</span>
                {option.tag !== undefined && <span className="shrink-0 text-[11px] text-ink-3">{option.tag}</span>}
                <span className={`shrink-0 text-ink ${option.key === picker?.value ? "" : "invisible"}`}>
                  <Icon size={13} strokeWidth={2.5}>
                    {GLYPHS.check}
                  </Icon>
                </span>
              </button>
            ))}
            {picker?.note !== undefined && <div className="mt-1 border-t border-line px-2 pt-1.5 pb-1 text-[11px] leading-4 text-ink-3">{picker.note}</div>}
          </div>
        )}

        {/* -- composer -- */}
        <div className="relative isolate flex flex-col gap-2.5 overflow-hidden rounded-[22px] border border-line bg-surface p-3.5 shadow-card transition-[border-color,border-radius] duration-150 focus-within:border-line-strong">
          {attached.length > 0 && (
            <div className="flex flex-wrap gap-2 px-1 pt-0.5">
              {attached.map((each) => (
                <span key={each.id} className="relative" title={each.file.name} style={{ animation: "pop-in 200ms cubic-bezier(0.23,1,0.32,1) both" }}>
                  <img src={each.url} alt={each.file.name} className="size-14 rounded-[10px] object-cover shadow-hairline" />
                  <button
                    type="button"
                    aria-label={`Remove ${each.file.name}`}
                    onClick={() => detach(each.id)}
                    className="absolute -top-1.5 -right-1.5 flex size-5 items-center justify-center rounded-full bg-surface text-ink-2 shadow-btn transition-colors duration-100 hover:text-ink"
                  >
                    <Icon size={10} strokeWidth={2.5}>
                      {GLYPHS.close}
                    </Icon>
                  </button>
                </span>
              ))}
            </div>
          )}

          <div className="grid grid-cols-[28px_auto_minmax(0,1fr)_28px] items-end gap-x-1 gap-y-1.5">
            <textarea
              ref={inputRef}
              rows={1}
              value={draft}
              autoFocus={autoFocus}
              disabled={disabled}
              onChange={(event) => {
                setDraft(event.target.value);
                setDismissed(false);
                setPlusOpen(false);
                setModelOpen(false);
              }}
              onPaste={(event) => {
                const files = [...event.clipboardData.files].filter((file) => file.type.startsWith("image/"));
                if (files.length === 0 || images === undefined) return;
                event.preventDefault();
                attach(files);
              }}
              onKeyDown={(event) => {
                if (menu !== null && rows.length > 0) {
                  if (event.key === "ArrowDown" || event.key === "ArrowUp") {
                    event.preventDefault();
                    setEngaged(true);
                    setActive((current) => (current + (event.key === "ArrowDown" ? 1 : rows.length - 1)) % rows.length);
                    return;
                  }
                  if ((event.key === "Enter" && !event.shiftKey && !event.nativeEvent.isComposing) || event.key === "Tab") {
                    event.preventDefault();
                    const row = rows[active];
                    if (row === undefined || row.disabled === true) return;
                    const command = menu === "slash" ? commands.find((each) => each.name === row.key) : undefined;
                    // Tab completes a command; Enter on its whole name runs it (its arguments are optional then).
                    if (command !== undefined && event.key === "Tab") setDraft(`/${command.name} `);
                    else if (command !== undefined && query === command.name) void runCommand(command.name, "");
                    else row.pick();
                    return;
                  }
                }
                if (event.key === "Escape") {
                  setDismissed(true);
                  setPlusOpen(false);
                  setModelOpen(false);
                  return;
                }
                if (event.key === "Enter" && !event.shiftKey && !event.nativeEvent.isComposing) {
                  event.preventDefault();
                  void send();
                }
              }}
              placeholder={placeholder ?? "Write a message…"}
              aria-label="Message"
              className="col-span-full col-start-1 row-start-1 min-h-[68px] w-full min-w-0 resize-none bg-transparent px-2 py-2 text-[14px] leading-5 text-ink outline-none [overflow-wrap:anywhere] placeholder:text-ink-3 disabled:opacity-60"
            />

            {/* "+": images, web search */}
            {images !== undefined || webSearch !== undefined ? (
              <button
                type="button"
                aria-label="Add images or web search"
                aria-expanded={plusOpen}
                disabled={disabled}
                onClick={() => {
                  setModelOpen(false);
                  setPlusOpen((current) => !current);
                  inputRef.current?.focus();
                }}
                className={`col-start-1 row-start-2 flex size-7 shrink-0 items-center justify-center justify-self-start rounded-[8px] text-ink-3 transition-[background-color,color,transform] duration-150 enabled:hover:bg-hover enabled:hover:text-ink enabled:active:scale-[0.94] disabled:opacity-50 ${plusOpen ? "bg-hover text-ink" : ""}`}
              >
                <Icon size={16} strokeWidth={2}>
                  <path d="M12 5v14M5 12h14" />
                </Icon>
              </button>
            ) : (
              <span className="col-start-1 row-start-2" />
            )}

            {/* picker */}
            {picker !== undefined ? (
              <button
                ref={modelRef}
                type="button"
                aria-expanded={choosable ? modelOpen : undefined}
                aria-label={choosable ? `Choose the ${picker.label}` : `The ${picker.label}`}
                disabled={!choosable}
                onClick={() => {
                  setPlusOpen(false);
                  setModelOpen((current) => !current);
                }}
                className="col-start-2 row-start-2 flex h-7 shrink-0 items-center gap-1 justify-self-start rounded-[8px] px-1.5 text-[12px] font-medium text-ink-2 transition-colors duration-150 enabled:hover:bg-hover enabled:hover:text-ink"
              >
                {chosen?.name ?? picker.value ?? `No ${picker.label}`}
                {choosable && (
                  <span className="text-ink-3">
                    <Icon size={11} strokeWidth={2.4}>
                      <path d="M6 9l6 6 6-6" />
                    </Icon>
                  </span>
                )}
              </button>
            ) : (
              <span className="col-start-2 row-start-2" />
            )}

            {/* web search on for the next message, or what was refused */}
            <div className="col-start-3 row-start-2 flex min-w-0 items-center gap-2 self-center pl-1">
              {webSearchOn && (
                <span className="flex h-6.5 shrink-0 items-center gap-1.5 rounded-chip bg-accent-tint py-1 pr-1 pl-1.5 text-[11.5px] font-medium text-accent-ink" style={{ animation: "pop-in 200ms cubic-bezier(0.23,1,0.32,1) both" }}>
                  <Icon size={12}>{GLYPHS.globe}</Icon>
                  Web search
                  <button
                    type="button"
                    aria-label="Turn web search off"
                    onClick={() => setSearching(false)}
                    className="-my-1 flex size-5 items-center justify-center rounded-[5px] transition-colors duration-100 hover:bg-accent-tint"
                  >
                    <Icon size={10} strokeWidth={2.5}>
                      {GLYPHS.close}
                    </Icon>
                  </button>
                </span>
              )}
              {problem !== undefined && (
                <span role="status" className="min-w-0 truncate text-[12px] text-red" title={problem}>
                  {problem}
                </span>
              )}
            </div>

            {/* send, or stop while a run goes */}
            <button
              type="button"
              aria-label={stopping ? "Stop the run" : "Send"}
              title={stopping ? "Stop the run" : busy ? "Send: it runs after the run going" : "Send"}
              disabled={!stopping && !canSend}
              onClick={stopping ? onStop : () => void send()}
              className="col-start-4 row-start-2 flex size-7 shrink-0 items-center justify-center rounded-[8px] transition-[background-color,color,transform] duration-200 enabled:active:scale-[0.94]"
              style={{
                background: canSend || stopping ? "var(--ink)" : "var(--line-strong)",
                color: canSend || stopping ? "var(--surface)" : "var(--ink-2)",
              }}
            >
              {stopping ? (
                <svg width="10" height="10" viewBox="0 0 10 10" aria-hidden>
                  <rect width="10" height="10" rx="2" fill="currentColor" />
                </svg>
              ) : sending ? (
                <span className="size-3 rounded-full border-[1.5px] border-current border-t-transparent" style={{ animation: "spin 700ms linear infinite" }} />
              ) : (
                <Icon size={16} strokeWidth={2.4}>
                  <path d="M12 19V5M5 12l7-7 7 7" />
                </Icon>
              )}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

import { type CSSProperties, type ReactNode, useLayoutEffect, useMemo, useRef, useState } from "react";

/* ---------------------------------------------------------
 * RECORDS TABLE
 * Beautiful UI's records grid, fed by the app: columns with
 * a glyph each, sorted from their header, a numbered gutter,
 * a first column that stays while the grid scrolls both ways,
 * and a footer with the count. The rows and what each cell
 * shows are the caller's; nothing is invented.
 * --------------------------------------------------------- */

export type RecordColumn<T> = {
  key: string;
  label: string;
  /** a glyph before the label (iconoir) */
  icon?: ReactNode;
  /** px; the table fills its width beyond their sum, and scrolls under it */
  width: number;
  cell: (row: T) => ReactNode;
  /** sortable from its header */
  sort?: (a: T, b: T) => number;
  /** figures: right-aligned, tabular */
  end?: boolean;
  /** the cell's text is quiet */
  muted?: (row: T) => boolean;
  /** the cell's tooltip */
  title?: (row: T) => string | undefined;
};

function Arrow() {
  return (
    <svg width={12} height={12} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={1.8} strokeLinecap="round" strokeLinejoin="round" aria-hidden>
      <path d="M12 5v14M5 12l7 7 7-7" />
    </svg>
  );
}

/** The record's initial in a small square, before its name. */
export function RecordMark({ name }: { name: string }) {
  return <span className="records-mark">{name.slice(0, 1).toUpperCase()}</span>;
}

/** A record's name, as the first column shows it. */
export function RecordName({ children, title }: { children: ReactNode; title?: string }) {
  return (
    <span className="records-name" title={title}>
      {children}
    </span>
  );
}

/* one mid-lightness base hue per tag; background, text and border are mixed from it */
const TAG_PALETTE = [
  "oklch(0.76 0.13 70)", // amber
  "oklch(0.77 0.16 122)", // lime
  "oklch(0.62 0.18 293)", // purple
  "oklch(0.71 0.16 48)", // orange
  "oklch(0.72 0.10 221)", // cyan
  "oklch(0.64 0.19 27)", // red
  "oklch(0.66 0.21 323)", // magenta
  "oklch(0.70 0.13 162)", // green
  "oklch(0.67 0.19 3)", // pink
  "oklch(0.80 0.15 101)", // yellow
];

/** A hue of the palette for `text`, always the same one: a name's tags share their colour wherever they show. */
export function tagHue(text: string): string {
  let hash = 0;
  for (const char of text) hash = (hash * 31 + (char.codePointAt(0) ?? 0)) >>> 0;
  return TAG_PALETTE[hash % TAG_PALETTE.length] as string;
}

/** A tag, its colours mixed from one hue (`base`, any CSS colour; quiet when absent). */
export function RecordTag({ children, base, title, mono = false }: { children: ReactNode; base?: string; title?: string; mono?: boolean }) {
  return (
    <span className={`records-tag ${mono ? "font-mono text-[12px]" : ""}`} title={title} style={base === undefined ? undefined : ({ "--tag-base": base } as CSSProperties)}>
      {children}
    </span>
  );
}

/** As many tags as fit the cell, then `+n`: the rest are in its tooltip. */
export function TagList({ tags, render, empty = "—" }: { tags: string[]; render: (tag: string) => ReactNode; empty?: ReactNode }) {
  const containerRef = useRef<HTMLDivElement>(null);
  const measureRef = useRef<HTMLDivElement>(null);
  const [visibleCount, setVisibleCount] = useState(tags.length);

  useLayoutEffect(() => {
    const container = containerRef.current;
    const measure = measureRef.current;
    if (!container || !measure) return;

    const update = () => {
      const available = container.clientWidth;
      const widths = Array.from(measure.querySelectorAll<HTMLElement>("[data-tag-measure]"), (tag) => tag.offsetWidth);
      const moreWidth = measure.querySelector<HTMLElement>("[data-more-measure]")?.offsetWidth ?? 0;
      let used = 0;
      let count = 0;
      for (let index = 0; index < widths.length; index += 1) {
        const nextUsed = used + (count > 0 ? 4 : 0) + (widths[index] ?? 0);
        const hiddenAfter = tags.length - (index + 1);
        if (nextUsed + (hiddenAfter > 0 ? 4 + moreWidth : 0) > available) break;
        used = nextUsed;
        count += 1;
      }
      setVisibleCount(count);
    };

    update();
    const observer = new ResizeObserver(update);
    observer.observe(container);
    return () => observer.disconnect();
  }, [tags]);

  if (tags.length === 0) return <span className="records-muted">{empty}</span>;
  const hiddenCount = tags.length - visibleCount;

  return (
    <div ref={containerRef} className="records-tags" title={tags.join(", ")}>
      <div ref={measureRef} className="records-tags-measure" aria-hidden>
        {tags.map((tag) => (
          <span key={tag} data-tag-measure>
            {render(tag)}
          </span>
        ))}
        <span data-more-measure className="records-more-tag">
          +{tags.length}
        </span>
      </div>
      {tags.slice(0, visibleCount).map((tag) => (
        <span key={tag} className="inline-flex">
          {render(tag)}
        </span>
      ))}
      {hiddenCount > 0 && <span className="records-more-tag">+{hiddenCount}</span>}
    </div>
  );
}

export default function RecordsTable<T>({
  label,
  columns,
  rows,
  rowKey,
  empty,
  initialSort,
  maxHeight = 520,
  className = "",
}: {
  /** what the table holds, for assistive technology */
  label: string;
  columns: RecordColumn<T>[];
  rows: T[];
  rowKey: (row: T) => string;
  /** shown under the header when there are no rows */
  empty: ReactNode;
  initialSort?: { key: string; dir: 1 | -1 };
  /** px before the grid scrolls under its sticky header */
  maxHeight?: number;
  className?: string;
}) {
  const [sort, setSort] = useState(initialSort);

  const sorted = useMemo(() => {
    const by = columns.find((column) => column.key === sort?.key)?.sort;
    if (by === undefined || sort === undefined) return rows;
    return [...rows].sort((a, b) => by(a, b) * sort.dir);
  }, [columns, rows, sort]);

  const toggle = (key: string) => setSort((current) => (current?.key === key ? { key, dir: (current.dir * -1) as 1 | -1 } : { key, dir: 1 }));
  const width = columns.reduce((sum, column) => sum + column.width, 0);

  return (
    <div className={`records-shell ${className}`}>
      <div className="records-scroll" tabIndex={0} role="region" aria-label={label} style={{ maxHeight }}>
        <table className="records-table" style={{ minWidth: width }}>
          <colgroup>
            {columns.map((column) => (
              <col key={column.key} style={{ width: column.width }} />
            ))}
          </colgroup>
          <thead>
            <tr>
              {columns.map((column, index) => {
                const content = (
                  <>
                    {column.icon !== undefined && <span className="records-header-icon">{column.icon}</span>}
                    <span className="truncate">{column.label}</span>
                    {column.sort !== undefined && (
                      <span className={`records-sort ${sort?.key === column.key ? "is-visible" : ""}`} style={{ transform: sort?.key === column.key && sort.dir === -1 ? "rotate(180deg)" : undefined }}>
                        <Arrow />
                      </span>
                    )}
                  </>
                );
                return (
                  <th
                    key={column.key}
                    className={index === 0 ? "records-sticky-cell" : undefined}
                    aria-sort={sort?.key === column.key ? (sort.dir === 1 ? "ascending" : "descending") : undefined}
                  >
                    {column.sort === undefined ? (
                      <div className="records-header-button">{content}</div>
                    ) : (
                      <button type="button" className="records-header-button" onClick={() => toggle(column.key)} aria-label={`Sort by ${column.label}`}>
                        {content}
                      </button>
                    )}
                  </th>
                );
              })}
            </tr>
          </thead>
          {/* data cells stay silent: a sound per row is too much when scanning */}
          <tbody data-sound-silent>
            {sorted.map((row, index) => (
              <tr key={rowKey(row)} className="records-row">
                {columns.map((column, at) => {
                  const classes = `records-cell ${at === 0 ? "records-sticky-cell" : ""} ${column.end === true ? "is-end" : ""} ${column.muted?.(row) === true ? "records-muted" : ""}`;
                  return (
                    <td key={column.key} className={classes} title={column.title?.(row)}>
                      {at === 0 ? (
                        <div className="records-first">
                          <span className="records-rownum">{index + 1}</span>
                          {column.cell(row)}
                        </div>
                      ) : (
                        column.cell(row)
                      )}
                    </td>
                  );
                })}
              </tr>
            ))}
          </tbody>
          {rows.length > 0 && (
            <tfoot>
              <tr>
                <td className="records-cell records-sticky-cell">
                  <span className="inline-flex h-[35px] items-center text-ink-2">
                    <span className="records-count">{rows.length}</span> count
                  </span>
                </td>
                {columns.slice(1).map((column) => (
                  <td key={column.key} className="records-cell" />
                ))}
              </tr>
            </tfoot>
          )}
        </table>
      </div>
      {rows.length === 0 && empty}
    </div>
  );
}

/* ---------------------------------------------------------
 * SEARCH FIELD
 * Beautiful UI's SearchList field, fed by the app: a glass,
 * the query, and a clear button once there is one. What it
 * filters is the caller's.
 * --------------------------------------------------------- */

export default function SearchField({ value, onChange, placeholder, label, className = "" }: { value: string; onChange: (value: string) => void; placeholder: string; label: string; className?: string }) {
  return (
    <div className={`flex h-8 items-center gap-2 rounded-control bg-surface px-2.5 shadow-btn transition-colors duration-100 focus-within:shadow-[0_0_0_1px_var(--line-strong),0_0_0_3px_var(--accent-tint)] ${className}`}>
      <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="var(--ink-3)" strokeWidth="2" strokeLinecap="round" className="shrink-0" aria-hidden>
        <circle cx="11" cy="11" r="7" />
        <path d="M21 21l-4.3-4.3" />
      </svg>
      <input
        value={value}
        onChange={(event) => onChange(event.target.value)}
        onKeyDown={(event) => event.key === "Escape" && onChange("")}
        placeholder={placeholder}
        aria-label={label}
        className="min-w-0 flex-1 bg-transparent text-[13px] text-ink outline-none placeholder:text-ink-3"
      />
      {value !== "" && (
        <button
          aria-label="Clear search"
          type="button"
          onClick={() => onChange("")}
          className="-mr-1 flex size-6 items-center justify-center rounded-full text-ink-3 transition-colors duration-100 hover:bg-hover-2 hover:text-ink"
          style={{ animation: "fade-in 150ms ease-out both" }}
        >
          <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" aria-hidden>
            <path d="M18 6L6 18M6 6l12 12" />
          </svg>
        </button>
      )}
    </div>
  );
}

import { useEffect, useRef, useState, type CSSProperties, type MouseEvent, type ReactNode } from "react";
import { createPortal } from "react-dom";
import { MoreHoriz, NavArrowDown, Search, Settings, SidebarCollapse, Xmark } from "iconoir-react";
import GlideMenu from "./GlideMenu";

/* ---------------------------------------------------------
 * SIDEBAR NAV
 * Beautiful UI's harness sidebar, fed by the app: the workspace
 * (its mark and name), primary navigation, a searchable list of
 * chats (each with its actions, archived ones apart), settings
 * at the foot, and a collapse that keeps every icon in place.
 * Icons: iconoir.
 * --------------------------------------------------------- */

export type SidebarItem = {
  key: string;
  label: string;
  icon: ReactNode;
  /** a short figure at the row's end */
  count?: string;
  active?: boolean;
  /** the link's target, for a new tab; a plain click calls `onSelect` */
  href?: string;
  onSelect: () => void;
};

/** What can be done to a chat from its row's menu. */
export type SidebarChatAction = { key: string; label: string; icon: ReactNode; danger?: boolean; onSelect: () => void };

export type SidebarChat = {
  id: string;
  label: string;
  busy?: boolean;
  active?: boolean;
  href?: string;
  /** its row's "…" menu; none, no menu */
  actions?: SidebarChatAction[];
};

const SIDEBAR_MOTION = {
  expandedWidth: 224,
  collapsedWidth: 52,
  duration: 280,
  copyDuration: 180,
  copyOffset: 8,
  easing: "cubic-bezier(0.16, 1, 0.3, 1)",
};

const CHAT_SEARCH_MOTION = {
  duration: 180,
  closedWidth: 28,
  easing: "cubic-bezier(0.16, 1, 0.3, 1)",
};

/** A plain left click follows `onSelect`; any other (a new tab) follows the link. */
function follow(event: MouseEvent, onSelect: () => void) {
  if (event.button !== 0 || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return;
  event.preventDefault();
  onSelect();
}

function GlideGroup({ children }: { children: ReactNode }) {
  return (
    <GlideMenu rowSelector="[data-row]" highlightClassName="sidebar-glide-highlight rounded-[7px] bg-hover-2" className="group/glide flex flex-col gap-px">
      {children}
    </GlideMenu>
  );
}

function RailButton({ item }: { item: SidebarItem }) {
  const { icon, label, active = false, count, href, onSelect } = item;
  return (
    <a
      data-row
      href={href}
      onClick={(event) => follow(event, onSelect)}
      aria-current={active ? "page" : undefined}
      title={label}
      className={`sidebar-row relative z-10 mx-2 flex h-8 items-center rounded-[8px] px-2 text-left transition-[width,background-color,color,transform] duration-150 active:scale-[0.98] ${active ? "bg-hover-2 group-hover/glide:bg-transparent" : ""}`}
    >
      <span className={`flex size-5 shrink-0 items-center justify-center [&_svg]:size-[18px] ${active ? "text-ink" : "text-ink-2"}`}>{icon}</span>
      <span className={`sidebar-copy ml-1.5 min-w-0 flex-1 truncate text-[14px] font-medium ${active ? "text-ink" : "text-ink-2"}`}>{label}</span>
      {count && <span className="sidebar-copy mr-2 shrink-0 text-[12px] font-medium tabular-nums text-ink-3">{count}</span>}
    </a>
  );
}

/** One row of the workspace menu. */
export function MenuRow({ icon, children, trailing, onClick, height = "h-9", danger = false }: { icon?: ReactNode; children: ReactNode; trailing?: ReactNode; onClick?: () => void; height?: string; danger?: boolean }) {
  return (
    <button data-menu-row type="button" onClick={onClick} className={`relative z-10 flex ${height} w-full items-center gap-1.5 rounded-[8px] px-2 text-left`}>
      {icon !== undefined && <span className={`flex size-5 shrink-0 items-center justify-center [&_svg]:size-4 ${danger ? "text-red" : "text-ink-2"}`}>{icon}</span>}
      <span className={`min-w-0 flex-1 truncate text-[13.5px] ${danger ? "text-red" : "text-ink"}`}>{children}</span>
      {trailing}
    </button>
  );
}

export function MenuSeparator() {
  return <div className="my-1 h-px bg-line" />;
}

/** A menu over everything, anchored at `position`: below a point (`top`), or above one (`bottom`). */
function WorkspaceMenu({ position, children, width = "w-64" }: { position: { top?: number; bottom?: number; left: number }; children: ReactNode; width?: string }) {
  const above = position.bottom !== undefined;
  return createPortal(
    <div
      data-workspace-menu
      className={`fixed z-50 ${width} rounded-[14px] bg-surface p-1.5 shadow-overlay`}
      style={{ top: position.top, bottom: position.bottom, left: position.left, animation: "pop-in 180ms cubic-bezier(0.23,1,0.32,1) both", transformOrigin: above ? "bottom left" : "top left" }}
    >
      <GlideMenu className="flex flex-col gap-px" highlightClassName="inset-x-0 rounded-[8px] bg-hover-2">
        {children}
      </GlideMenu>
    </div>,
    document.body,
  );
}

export default function SidebarNav({
  workspace,
  menu,
  items,
  chats,
  onPickChat,
  chatsFooter,
  archived,
  chatsEmpty = "No chats yet",
  defaultCollapsed = false,
  className = "",
}: {
  workspace: { name: string; logo: ReactNode };
  /** the settings menu's rows (`MenuRow`, `MenuSeparator`), opened from the foot; `close` closes it */
  menu: (close: () => void) => ReactNode;
  /** the chats put away: listed apart, read when opened (`onOpen`); `undefined` until read */
  archived?: { chats: SidebarChat[] | undefined; onOpen: () => void };
  items: SidebarItem[];
  chats: SidebarChat[];
  onPickChat: (id: string) => void;
  /** after the chats: "older" */
  chatsFooter?: ReactNode;
  chatsEmpty?: string;
  defaultCollapsed?: boolean;
  className?: string;
}) {
  const [collapsed, setCollapsed] = useState(defaultCollapsed);
  const [workspaceOpen, setWorkspaceOpen] = useState(false);
  const [workspacePosition, setWorkspacePosition] = useState<{ top?: number; bottom?: number; left: number }>({ left: 0 });
  const [chatsOpen, setChatsOpen] = useState(true);
  const [archivedOpen, setArchivedOpen] = useState(false);
  /** The chat whose "…" menu is open, and where. */
  const [rowMenu, setRowMenu] = useState<{ chat: SidebarChat; top: number; left: number }>();
  const [searchOpen, setSearchOpen] = useState(false);
  const [query, setQuery] = useState("");
  const workspaceButtonRef = useRef<HTMLButtonElement>(null);
  const searchRef = useRef<HTMLInputElement>(null);

  const needle = query.trim().toLowerCase();
  const visibleChats = chats.filter((chat) => chat.label.toLowerCase().includes(needle));

  useEffect(() => {
    if (!workspaceOpen) return;
    const close = (event: PointerEvent) => {
      const target = event.target as Element;
      if (!target.closest("[data-workspace-trigger]") && !target.closest("[data-workspace-menu]")) setWorkspaceOpen(false);
    };
    const escape = (event: KeyboardEvent) => event.key === "Escape" && setWorkspaceOpen(false);
    document.addEventListener("pointerdown", close);
    document.addEventListener("keydown", escape);
    return () => {
      document.removeEventListener("pointerdown", close);
      document.removeEventListener("keydown", escape);
    };
  }, [workspaceOpen]);

  useEffect(() => {
    if (searchOpen) searchRef.current?.focus();
  }, [searchOpen]);

  useEffect(() => {
    if (rowMenu === undefined) return;
    const close = (event: PointerEvent) => {
      const target = event.target as Element;
      if (!target.closest("[data-workspace-menu]") && !target.closest("[data-row-menu-trigger]")) setRowMenu(undefined);
    };
    const escape = (event: KeyboardEvent) => event.key === "Escape" && setRowMenu(undefined);
    document.addEventListener("pointerdown", close);
    document.addEventListener("keydown", escape);
    return () => {
      document.removeEventListener("pointerdown", close);
      document.removeEventListener("keydown", escape);
    };
  }, [rowMenu]);

  const collapse = () => {
    setCollapsed(true);
    setWorkspaceOpen(false);
    setRowMenu(undefined);
    setSearchOpen(false);
    setQuery("");
  };

  return (
    <aside
      data-sidebar-collapsed={collapsed}
      aria-label="Navigation"
      className={`relative flex h-full shrink-0 overflow-hidden transition-[width] ${className}`}
      style={
        {
          width: collapsed ? SIDEBAR_MOTION.collapsedWidth : SIDEBAR_MOTION.expandedWidth,
          transitionDuration: `${SIDEBAR_MOTION.duration}ms`,
          transitionTimingFunction: SIDEBAR_MOTION.easing,
          "--sidebar-copy-duration": `${SIDEBAR_MOTION.copyDuration}ms`,
          "--sidebar-copy-offset": `${SIDEBAR_MOTION.copyOffset}px`,
          "--sidebar-easing": SIDEBAR_MOTION.easing,
        } as CSSProperties
      }
    >
      <div className="flex min-h-0 w-[224px] shrink-0 flex-col">
        <div className="relative mb-2.5 h-10 shrink-0">
          <div aria-hidden={collapsed} className="sidebar-workspace-control absolute top-1 left-2 flex h-8 w-[164px] items-center px-2">
            <span className="sidebar-logo flex size-5 shrink-0 items-center justify-center text-ink">{workspace.logo}</span>
            <span className="sidebar-copy ml-1.5 min-w-0 flex-1 truncate text-[14px] font-medium text-ink">{workspace.name}</span>
          </div>

          <button
            type="button"
            aria-label="Collapse sidebar"
            aria-hidden={collapsed}
            tabIndex={collapsed ? -1 : 0}
            onClick={collapse}
            className="sidebar-collapse-control absolute top-1 right-2 flex size-8 items-center justify-center rounded-[8px] text-ink-3 transition-[opacity,background-color,color] duration-150 hover:bg-hover-2 hover:text-ink"
          >
            <SidebarCollapse width={18} height={18} />
          </button>
          <button
            type="button"
            aria-label="Expand sidebar"
            aria-hidden={!collapsed}
            tabIndex={collapsed ? 0 : -1}
            onClick={() => setCollapsed(false)}
            className="sidebar-expand-control absolute top-0.5 left-2 flex size-9 items-center justify-center rounded-[8px] text-ink-3 transition-[opacity,background-color,color] duration-150 hover:bg-hover-2 hover:text-ink"
          >
            <SidebarCollapse width={18} height={18} className="rotate-180" />
          </button>
        </div>

        <GlideGroup>
          {items.map((item) => (
            <RailButton key={item.key} item={item} />
          ))}
        </GlideGroup>

        {/* collapsed, the chats have no icon to keep: they go, with the active one's highlight */}
        <div className="sidebar-chats mt-3 min-h-0 flex-1 overflow-y-auto" inert={collapsed}>
          <div className="sidebar-copy relative mx-2 mb-1 h-8">
            <button
              type="button"
              aria-hidden={searchOpen}
              aria-expanded={chatsOpen}
              tabIndex={searchOpen ? -1 : 0}
              onClick={() => setChatsOpen((open) => !open)}
              className={`absolute inset-y-0 left-0 flex items-center gap-1.5 rounded-[8px] px-2 text-[12.5px] font-medium text-ink-3 transition-[opacity,transform,color] hover:text-ink-2 ${searchOpen ? "pointer-events-none -translate-x-1 opacity-0" : "translate-x-0 opacity-100"}`}
              style={{ transitionDuration: `${CHAT_SEARCH_MOTION.duration}ms`, transitionTimingFunction: CHAT_SEARCH_MOTION.easing }}
            >
              <NavArrowDown width={16} height={16} strokeWidth={2} className="transition-transform duration-200" style={{ transform: chatsOpen ? "rotate(0deg)" : "rotate(-90deg)" }} />
              <span>Chats</span>
            </button>

            <button
              type="button"
              aria-label="Search chats"
              aria-expanded={searchOpen}
              onClick={() => {
                setChatsOpen(true);
                setSearchOpen(true);
              }}
              className={`absolute top-0 right-0 z-10 flex size-8 items-center justify-center rounded-[8px] text-ink-3 transition-[opacity,background-color,color,transform] hover:bg-hover-2 hover:text-ink active:scale-[0.96] ${searchOpen ? "pointer-events-none opacity-0" : "opacity-100"}`}
              style={{ transitionDuration: `${CHAT_SEARCH_MOTION.duration}ms` }}
            >
              <Search width={16} height={16} strokeWidth={1.8} />
            </button>

            <div
              className={`absolute top-0 right-0 z-20 flex h-8 items-center overflow-hidden rounded-[8px] bg-field text-ink-3 shadow-hairline transition-[width,opacity] focus-within:text-ink-2 ${searchOpen ? "pointer-events-auto opacity-100" : "pointer-events-none opacity-0"}`}
              style={{ width: searchOpen ? "100%" : CHAT_SEARCH_MOTION.closedWidth, transitionDuration: `${CHAT_SEARCH_MOTION.duration}ms`, transitionTimingFunction: CHAT_SEARCH_MOTION.easing }}
            >
              <span className="ml-2 flex shrink-0 items-center justify-center">
                <Search width={15} height={15} strokeWidth={1.8} />
              </span>
              <input
                ref={searchRef}
                value={query}
                tabIndex={searchOpen ? 0 : -1}
                onChange={(event) => setQuery(event.target.value)}
                onKeyDown={(event) => {
                  if (event.key === "Escape") {
                    setSearchOpen(false);
                    setQuery("");
                  }
                }}
                placeholder="Search chats"
                aria-label="Search the chats"
                className="ml-1.5 min-w-0 flex-1 bg-transparent text-[13px] font-medium text-ink outline-none placeholder:text-ink-3"
              />
              <button
                type="button"
                aria-label="Close chat search"
                tabIndex={searchOpen ? 0 : -1}
                onClick={() => {
                  setSearchOpen(false);
                  setQuery("");
                }}
                className="flex size-8 shrink-0 items-center justify-center rounded-[8px] text-ink-3 transition-[background-color,color,transform] duration-150 hover:bg-hover-2 hover:text-ink active:scale-[0.96]"
              >
                <Xmark width={16} height={16} strokeWidth={1.8} />
              </button>
            </div>
          </div>

          {chatsOpen && (
            <GlideGroup>
              {visibleChats.map((chat) => (
                <ChatRow key={chat.id} chat={chat} menuOpen={rowMenu?.chat.id === chat.id} onPick={onPickChat} onMenu={(at) => setRowMenu(rowMenu?.chat.id === chat.id ? undefined : { chat, ...at })} />
              ))}
              {visibleChats.length === 0 && <div className="sidebar-copy mx-2 px-2 py-2 text-[12.5px] text-ink-3">{needle === "" ? chatsEmpty : "No chats found"}</div>}
              {chatsFooter}
            </GlideGroup>
          )}

          {archived !== undefined && (
            <div className="mt-3">
              <button
                type="button"
                aria-expanded={archivedOpen}
                onClick={() => {
                  if (!archivedOpen) archived.onOpen();
                  setArchivedOpen((open) => !open);
                }}
                className="sidebar-copy mx-2 flex h-8 items-center gap-1.5 rounded-[8px] px-2 text-[12.5px] font-medium text-ink-3 transition-colors hover:text-ink-2"
              >
                <NavArrowDown width={16} height={16} strokeWidth={2} className="transition-transform duration-200" style={{ transform: archivedOpen ? "rotate(0deg)" : "rotate(-90deg)" }} />
                <span>Archived</span>
              </button>
              {archivedOpen && (
                <GlideGroup>
                  {(archived.chats ?? []).map((chat) => (
                    <ChatRow key={chat.id} chat={chat} menuOpen={rowMenu?.chat.id === chat.id} onPick={onPickChat} onMenu={(at) => setRowMenu(rowMenu?.chat.id === chat.id ? undefined : { chat, ...at })} />
                  ))}
                  {archived.chats !== undefined && archived.chats.length === 0 && <div className="sidebar-copy mx-2 px-2 py-2 text-[12.5px] text-ink-3">No archived chats</div>}
                  {archived.chats === undefined && <div className="sidebar-copy mx-2 px-2 py-2 text-[12.5px] text-ink-3">Loading</div>}
                </GlideGroup>
              )}
            </div>
          )}
        </div>

        {/* settings, at the foot: as round as the chat's composer, its border and its shade */}
        <div className="shrink-0 px-2 pt-2">
          <button
            ref={workspaceButtonRef}
            data-workspace-trigger
            type="button"
            aria-label="Settings"
            aria-expanded={workspaceOpen}
            title="Settings"
            onClick={() => {
              if (!workspaceOpen && workspaceButtonRef.current) {
                const rect = workspaceButtonRef.current.getBoundingClientRect();
                setWorkspacePosition({ bottom: window.innerHeight - rect.top + 8, left: rect.left });
              }
              setWorkspaceOpen((open) => !open);
            }}
            className={`sidebar-settings flex h-9 w-full items-center gap-2 rounded-[14px] border bg-surface px-[9px] text-[13.5px] font-medium text-ink-2 shadow-card transition-[border-color,color,transform] duration-150 hover:border-line-strong hover:text-ink active:scale-[0.98] ${workspaceOpen ? "border-line-strong text-ink" : "border-line"}`}
          >
            <Settings width={17} height={17} strokeWidth={1.8} className="shrink-0" />
            <span className="sidebar-copy min-w-0 truncate">Settings</span>
          </button>
          {workspaceOpen && <WorkspaceMenu position={workspacePosition}>{menu(() => setWorkspaceOpen(false))}</WorkspaceMenu>}
        </div>
      </div>

      {rowMenu !== undefined && (
        <WorkspaceMenu position={{ top: rowMenu.top, left: rowMenu.left }} width="w-44">
          {(rowMenu.chat.actions ?? []).map((action) => (
            <MenuRow
              key={action.key}
              icon={action.icon}
              danger={action.danger === true}
              onClick={() => {
                setRowMenu(undefined);
                action.onSelect();
              }}
            >
              {action.label}
            </MenuRow>
          ))}
        </WorkspaceMenu>
      )}
    </aside>
  );
}

/** One chat of the list: its link, and, on hover or focus, its "…" menu's trigger when it has actions. */
function ChatRow({ chat, menuOpen, onPick, onMenu }: { chat: SidebarChat; menuOpen: boolean; onPick: (id: string) => void; onMenu: (at: { top: number; left: number }) => void }) {
  const withMenu = (chat.actions?.length ?? 0) > 0;
  return (
    <div className="group/chat relative">
      <a
        data-row
        href={chat.href}
        title={chat.label}
        aria-current={chat.active ? "page" : undefined}
        onClick={(event) => follow(event, () => onPick(chat.id))}
        className={`sidebar-row relative z-10 mx-2 flex h-8 items-center gap-2 rounded-[8px] px-2 text-left transition-[width,background-color,color,transform] duration-150 active:scale-[0.98] ${chat.active ? "bg-hover-2 group-hover/glide:bg-transparent" : ""} ${withMenu ? "pr-8" : ""}`}
      >
        <span className={`sidebar-copy min-w-0 flex-1 truncate text-[14px] font-medium ${chat.active ? "text-ink" : "text-ink-2"}`}>{chat.label}</span>
        {chat.busy === true && (
          <span aria-label="Running" className="sidebar-copy size-3 shrink-0 rounded-full border-[1.5px] border-line-strong border-t-ink-2" style={{ animation: "spin 700ms linear infinite" }} />
        )}
      </a>
      {withMenu && (
        <button
          type="button"
          data-row-menu-trigger
          aria-label={`Actions for ${chat.label}`}
          aria-expanded={menuOpen}
          onClick={(event) => {
            const rect = event.currentTarget.getBoundingClientRect();
            onMenu({ top: rect.bottom + 4, left: Math.max(8, rect.right - 176) });
          }}
          className={`sidebar-copy absolute top-1 right-3 z-20 flex size-6 items-center justify-center rounded-[6px] text-ink-3 transition-[opacity,background-color,color] duration-100 hover:bg-hover-2 hover:text-ink focus-visible:opacity-100 ${menuOpen ? "bg-hover-2 text-ink opacity-100" : "opacity-0 group-hover/chat:opacity-100"}`}
        >
          <MoreHoriz width={16} height={16} strokeWidth={2} />
        </button>
      )}
    </div>
  );
}

import type { ReactNode } from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";

const statusPillVariants = cva("inline-flex h-6 items-center gap-1.5 rounded-full px-2.5 text-[13px] font-medium leading-none", {
  variants: {
    tone: {
      green: "bg-green-tint text-green",
      orange: "bg-orange-tint text-orange",
      red: "bg-red-tint text-red",
      accent: "bg-accent-tint text-accent-ink",
      neutral: "bg-inset text-ink-2",
    },
  },
  defaultVariants: { tone: "neutral" },
});

export type Tone = NonNullable<VariantProps<typeof statusPillVariants>["tone"]>;

/* the leading dot lives on a separate element, so its color stays a small lookup */
const dotColor: Record<Tone, string> = {
  green: "bg-green",
  orange: "bg-orange",
  red: "bg-red",
  accent: "bg-accent-blue",
  neutral: "bg-ink-3",
};

export function StatusPill({ tone = "neutral", children, dot = true, className }: { tone?: Tone; children: ReactNode; dot?: boolean; className?: string }) {
  return (
    <span className={cn(statusPillVariants({ tone }), className)}>
      {dot && <span className={cn("size-1.5 rounded-full", dotColor[tone])} />}
      {children}
    </span>
  );
}

/* ---------------------------------------------------------
 * STREAM TEXT
 * Beautiful UI's streaming atom, fed by a live stream instead of a
 * timer: `text` is what arrived so far. While `streaming`, the
 * newest characters resolve out of a soft blur and the caret holds
 * solid; once settled the text stands alone. Inherits typography.
 * --------------------------------------------------------- */

export function StreamText({
  text,
  streaming,
  blurTail = 6,
  className,
}: {
  text: string;
  streaming: boolean;
  /** how many trailing characters carry the soft blur edge */
  blurTail?: number;
  className?: string;
}) {
  const split = streaming ? Math.max(0, text.length - blurTail) : text.length;
  return (
    <span className={className}>
      {text.slice(0, split)}
      {split < text.length && <span className="stream-tail">{text.slice(split)}</span>}
      {streaming && <span aria-hidden className="stream-caret is-streaming" />}
    </span>
  );
}

/** A switch: `md` is Beautiful UI's atom, `sm` the harness's compact one (for menu rows). */
export function Switch({ checked, onChange, label, size = "md" }: { checked: boolean; onChange?: (value: boolean) => void; label?: string; size?: "sm" | "md" }) {
  const small = size === "sm";
  return (
    <span
      role="switch"
      aria-checked={checked}
      aria-label={label}
      tabIndex={onChange === undefined ? -1 : 0}
      onClick={onChange === undefined ? undefined : () => onChange(!checked)}
      onKeyDown={(event) => {
        if (onChange !== undefined && (event.key === " " || event.key === "Enter")) {
          event.preventDefault();
          onChange(!checked);
        }
      }}
      className={`relative inline-block shrink-0 rounded-full align-middle transition-colors duration-200 ${small ? "h-4.5 w-7.5" : "h-6 w-10"} ${checked ? (small ? "bg-accent-blue" : "bg-ink") : "bg-line-strong"}`}
    >
      <span
        className={`absolute top-0.5 left-0.5 rounded-full bg-white shadow-[0_1px_2px_rgba(0,0,0,0.2)] transition-transform duration-200 ${small ? "size-3.5" : "size-5"}`}
        style={{
          transform: checked ? `translateX(${small ? 12 : 16}px)` : "translateX(0)",
          transitionTimingFunction: "cubic-bezier(0.23, 1, 0.32, 1)",
        }}
      />
    </span>
  );
}

import { Computer, HalfMoon, SunLight } from "iconoir-react";
import { setTheme, type Theme, useTheme } from "@/lib/theme";

const OPTIONS: { value: Theme; label: string; icon: typeof SunLight }[] = [
  { value: "light", label: "Light mode", icon: SunLight },
  { value: "dark", label: "Dark mode", icon: HalfMoon },
  { value: "system", label: "The system's theme", icon: Computer },
];

/** Beautiful UI's sun/moon segmented pill, with a third segment: the system's theme (`lib/theme.ts`). */
export function ThemeToggle() {
  const theme = useTheme();
  const index = OPTIONS.findIndex((option) => option.value === theme);

  return (
    <div role="radiogroup" aria-label="Theme" className="relative inline-grid h-8 grid-cols-3 items-center rounded-full bg-field p-0.5">
      <span
        aria-hidden
        className="absolute inset-y-0.5 left-0.5 w-7 rounded-full bg-surface shadow-btn transition-transform duration-200"
        style={{ transform: `translateX(${index * 28}px)`, transitionTimingFunction: "cubic-bezier(0.23, 1, 0.32, 1)" }}
      />
      {OPTIONS.map(({ value, label, icon: Icon }) => (
        <button
          key={value}
          type="button"
          role="radio"
          aria-checked={theme === value}
          aria-label={label}
          title={label}
          onClick={() => setTheme(value)}
          className={`relative z-10 flex size-7 items-center justify-center rounded-full transition-colors duration-150 ${theme === value ? "text-ink" : "text-ink-3 hover:text-ink-2"}`}
        >
          <Icon width={14} height={14} strokeWidth={2} />
        </button>
      ))}
    </div>
